        signature=re.sub(r'\d','d',str(s))
        counts[signature]=counts.get(signature,0)+1
    print('\n',farm,'sep',sep,'col',repr(col),'duplicates',df.duplicated().sum(),'formats',counts)
    print('tail:',df[[df.columns[0],col,'inverter_temperature_C']].tail(8).to_dict('records'))
